import { Transform } from 'node:stream';

export class NDJSONParserStream extends Transform {
  constructor(options = {}) {
    super({ ...options, readableObjectMode: true });
    this._buffer = '';
  }

  _transform(chunk, encoding, callback) {
    this._buffer += chunk.toString('utf8');
    const lines = this._buffer.split('\n');
    // Keep the last incomplete fragment in the buffer
    this._buffer = lines.pop();

    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed) continue;
      try {
        const parsed = JSON.parse(trimmed);
        this.push(parsed);
      } catch (err) {
        return callback(new Error(`Malformed NDJSON line: ${err.message}`));
      }
    }
    callback();
  }

  _flush(callback) {
    if (this._buffer.trim()) {
      try {
        const parsed = JSON.parse(this._buffer.trim());
        this.push(parsed);
      } catch (err) {
        return callback(new Error(`Malformed NDJSON trailing line: ${err.message}`));
      }
    }
    callback();
  }
}
