import crypto from 'node:crypto';

const ALGORITHM = 'aes-256-gcm';
const IV_LENGTH = 12; // Recommended 96 bits for GCM
const TAG_LENGTH = 16;

export interface EncryptedPayload {
  iv: string;
  tag: string;
  ciphertext: string;
}

export function encryptData(plainText: string, masterKey: Buffer): EncryptedPayload {
  if (masterKey.length !== 32) {
    throw new Error('Master key must be exactly 32 bytes (256 bits).');
  }

  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv(ALGORITHM, masterKey, iv, { authTagLength: TAG_LENGTH });

  let ciphertext = cipher.update(plainText, 'utf8', 'hex');
  ciphertext += cipher.final('hex');
  const tag = cipher.getAuthTag();

  return {
    iv: iv.toString('hex'),
    tag: tag.toString('hex'),
    ciphertext,
  };
}

export function decryptData(payload: EncryptedPayload, masterKey: Buffer): string {
  if (masterKey.length !== 32) {
    throw new Error('Master key must be exactly 32 bytes.');
  }

  const iv = Buffer.from(payload.iv, 'hex');
  const tag = Buffer.from(payload.tag, 'hex');
  const decipher = crypto.createDecipheriv(ALGORITHM, masterKey, iv, { authTagLength: TAG_LENGTH });

  decipher.setAuthTag(tag);
  let decrypted = decipher.update(payload.ciphertext, 'hex', 'utf8');
  decrypted += decipher.final('utf8'); // Throws Error if authentication tag mismatch

  return decrypted;
}
